def compute(vars):
    goodwill = vars["Goodwill"]
    purchase_price = vars["Purchase Price"]

    # Normalize Purchase Price from millions to thousands to match Goodwill.
    purchase_price_in_thousands = purchase_price * 1000.0

    fair_value_identifiable_net_assets = -goodwill + purchase_price_in_thousands

    return {
        "value": fair_value_identifiable_net_assets,
        "trace": {
            "Goodwill": goodwill,
            "Purchase Price": purchase_price_in_thousands,
            "output_meta": {
                "currency": "$",
                "scale": "thousands",
                "unit": None
            }
        }
    }
